(function(C){
  C.platforms={
    tieba:{name:'百度贴吧',captureHosts:['tieba.baidu.com'],requestHosts:['tieba.baidu.com'],required:['BDUSS'],allowed:['BDUSS','BDUSS_BFESS'],level:'显式清单 · 待账号验证'},
    bilibili:{name:'哔哩哔哩',captureHosts:['www.bilibili.com','api.bilibili.com','live.bilibili.com','api.live.bilibili.com'],requestHosts:['api.bilibili.com','api.live.bilibili.com'],required:['SESSDATA','bili_jct','DedeUserID'],allowed:['SESSDATA','bili_jct','DedeUserID'],level:'直播每日签到 · 待账号验证'},
    smzdm:{name:'什么值得买',captureHosts:['zhiyou.smzdm.com'],requestHosts:['zhiyou.smzdm.com'],required:['sess'],allowed:['sess'],level:'接口待核实 · 暂不支持'}
  };
  C.parseCookie=function(id,text){
    var p=C.platforms[id];if(!p||typeof text!=='string'||text.length>16384||/[\x00-\x1f\x7f]/.test(text))throw C.error('incomplete');
    var fields={};text.split(';').forEach(function(part){var at=part.indexOf('=');if(at<1)return;var k=part.slice(0,at).trim(),v=part.slice(at+1).trim();if(p.allowed.indexOf(k)<0)return;if(C.own(fields,k)||!v||v.length>8192||/[\s;,]/.test(v))throw C.error('incomplete');fields[k]=v;});
    p.required.forEach(function(k){if(!fields[k])throw C.error('incomplete');});
    return p.allowed.filter(function(k){return C.own(fields,k);}).map(function(k){return k+'='+fields[k];}).join('; ');
  };
  C.saveCookie=function(id,text,source){
    var normalized=C.parseCookie(id,text),old=C.readCredential(id);
    if(old&&old.cookie===normalized){old.capturedAt=C.iso();old.source=source;C.storage.write('cred.'+id,old);return false;}
    C.storage.write('cred.'+id,{v:1,cookie:normalized,revision:C.token(),capturedAt:C.iso(),source:source,status:'captured',validatedAt:null});return true;
  };
  C.markCredential=function(id,revision,status){
    var c=C.readCredential(id);if(!c||c.revision!==revision)return;
    c.status=status;c.validatedAt=C.iso();C.storage.write('cred.'+id,c);
  };
  C.capture=function(request,config){
    if(!config.capture||!request)return {captured:false};
    var host=C.host(request.url),id=C.ids.filter(function(p){return C.platforms[p].captureHosts.indexOf(host)>=0;})[0];
    if(!id)return {captured:false};
    var headers=request.headers||{},keys=Object.keys(headers).filter(function(k){return k.toLowerCase()==='cookie';});
    if(keys.length!==1||typeof headers[keys[0]]!=='string')return {captured:false};
    try{return {captured:true,changed:C.saveCookie(id,headers[keys[0]],'capture'),platform:id};}
    catch(e){if(e.cc==='incomplete')return {captured:false};throw e;}
  };
  C.cookieLabel=function(c){return !c?'未获取':({captured:'已获取 · 待验证',valid:'有效',suspect:'可能失效',expired:'已失效',validation_failed:'验证失败',absent:'未获取'})[c.status]||'验证失败';};
})(CC);


