/* source: scripts/adapters/tieba.js */
(function(C){
  var id='tieba';
  var adapter={id:id,name:'百度贴吧 · 明确清单',
    checkLogin:async function(ctx){
      var j=await ctx.request('GET','https://tieba.baidu.com/dc/common/tbs',{readOnly:true});
      if(j.is_login===0||j.is_login==='0')return C.result(id,'expired','expired');
      if((j.is_login!==1&&j.is_login!=='1')||typeof j.tbs!=='string'||!/^[a-zA-Z0-9]{8,128}$/.test(j.tbs))return C.result(id,'failed','schema');
      ctx._tiebaTbs=j.tbs;
      return C.result(id,'success','valid',{loggedIn:true});
    },
    validateCookie:async function(ctx){return adapter.checkLogin(ctx);},
    getStatus:async function(ctx){
      var j=await ctx.request('GET','https://tieba.baidu.com/mo/q/newmoindex',{readOnly:true});
      if(!j.data||!Array.isArray(j.data.like_forum))return C.result(id,'failed','schema');
      var boards=j.data.like_forum,seen={};
      for(var i=0;i<boards.length;i++){
        var b=boards[i];
        if(!b||typeof b.forum_name!=='string'||!b.forum_name||b.forum_name.length>80||[0,1,'0','1'].indexOf(b.is_sign)<0||C.own(seen,b.forum_name))return C.result(id,'failed','schema');
        seen[b.forum_name]=true;
      }
      ctx._tiebaBoards=boards;
      var chosen=ctx.settings.forum_allowlist;
      if(!chosen.length)return C.result(id,'unsupported','scope',{observed:boards.length,completeCatalogue:false});
      var selected=boards.filter(function(b){return chosen.indexOf(b.forum_name)>=0;});
      if(selected.length!==chosen.length)return C.result(id,'unsupported','no_forums',{observed:boards.length,requested:chosen.length,matched:selected.length,completeCatalogue:false});
      ctx._tiebaSelected=selected;
      var done=selected.filter(function(b){return String(b.is_sign)==='1';}).length;
      return C.result(id,done===selected.length?'already':'skipped',done===selected.length?'already':'status',{requested:chosen.length,already:done,explicitScope:true,completeCatalogue:false});
    },
    checkin:async function(ctx){
      var before=await adapter.getStatus(ctx);if(before.status!=='skipped')return before;
      if(!ctx._tiebaTbs)return C.result(id,'failed','schema');
      var selected=ctx._tiebaSelected,done=0,already=0,failed=0,halt=false;
      for(var i=0;i<selected.length;i++){
        var b=selected[i];
        if(String(b.is_sign)==='1'){already++;continue;}
        if(halt){failed++;continue;}
        try{
          ctx.assertActive();
          if(ctx.deadline-C.now()<4000)throw C.error('budget');
          if(i>0)await C.wait(1200);
          var j=await ctx.request('POST','https://tieba.baidu.com/sign/add',{body:C.form({ie:'utf-8',kw:b.forum_name,tbs:ctx._tiebaTbs}),headers:{'Content-Type':'application/x-www-form-urlencoded',Referer:'https://tieba.baidu.com/'}});
          if(j.no===0){done++;}
          else if(j.no===1101){already++;}
          else {failed++;if(j.no===1102||j.no===2150040)halt=true;}
        }catch(e){failed++;halt=true;}
      }
      var d={requested:selected.length,signed:done,already:already,failed:failed,explicitScope:true,completeCatalogue:false};
      if(failed)return C.result(id,'failed','partial',d);
      if(done+already!==selected.length)return C.result(id,'failed','partial',d);
      return C.result(id,done?'success':'already',done?'signed':'already',d);
    }
  };C.adapters[id]=adapter;
})(CC);


