/* source: lib/statistics.js */
(function(C){
  C.dateOffset=function(n){var d=new Date(C.now());d.setDate(d.getDate()-n);return C.day(d.getTime());};
  C.record=function(id,result,mode,state){
    var s=state||C.readState(id),day=C.day(),safe=C.result(id,result.status,result.messageKey,result.details,result.reward);
    safe.time=result.time||C.iso();safe.date=day;safe.mode=mode;
    s.last=safe;s.total++;
    s.history.push(safe);
    s.history=s.history.filter(function(r){return r&&typeof r.date==='string'&&r.date>=C.dateOffset(29);}).slice(-240);
    if(!s.daily[day])s.daily[day]={success:0,already:0,failed:0,expired:0,skipped:0,unsupported:0};
    s.daily[day][safe.status]=(s.daily[day][safe.status]||0)+1;
    Object.keys(s.daily).forEach(function(d){if(d<C.dateOffset(29))delete s.daily[d];});
    s.running=null;C.storage.write('state.'+id,s);return safe;
  };
  C.getStatistics=function(days,filter){
    var data={today:{success:0,already:0,failed:0,skipped:0,pending:0,unsupported:0},completed:0,total:0,executions:0,history:[],platforms:{}};
    C.ids.forEach(function(id){
      var s=C.readState(id),today=s.history.filter(function(r){return r.date===C.day();});
      var good=today.filter(function(r){return r.status==='success'||r.status==='already';});
      var latest=good.length?good[good.length-1]:(today.length?today[today.length-1]:null);
      var count={success:0,already:0,failed:0,expired:0,skipped:0,unsupported:0};
      Object.keys(s.daily).forEach(function(day){if(day>=C.dateOffset(days-1))Object.keys(count).forEach(function(k){count[k]+=Number(s.daily[day][k])||0;});});
      var denominator=count.success+count.already+count.failed+count.expired;
      var streak=0;for(var n=0;n<30;n++){var d=s.daily[C.dateOffset(n)];if(d&&(d.success+d.already)>0)streak++;else break;}
      data.platforms[id]={last:s.last,today:latest,total:s.total,counts:count,successRate:denominator?Math.round((count.success+count.already)/denominator*100):null,observedStreak:streak||null};
      if(filter!=='all'&&filter!==id)return;
      data.total++;data.executions+=s.total;
      if(!latest)data.today.pending++;
      else if(latest.status==='success'){data.today.success++;data.completed++;}
      else if(latest.status==='already'){data.today.already++;data.completed++;}
      else if(latest.status==='expired'||latest.status==='failed')data.today.failed++;
      else if(latest.status==='unsupported')data.today.unsupported++;
      else data.today.skipped++;
      data.history=data.history.concat(s.history.filter(function(r){return r.date>=C.dateOffset(days-1);}));
    });
    data.history.sort(function(a,b){return b.time.localeCompare(a.time);});return data;
  };
})(CC);


/* source: lib/checkin-engine.js */
(function(C){
  C.due=function(id,config,state){
    var p=config.platforms[id],when=p.time==='follow'?config.time:p.time;
    return config.auto&&p.enabled&&p.auto&&C.hm()>=when&&state.autoDay!==C.day();
  };
  C.execute=async function(id,mode,config,lease,globalDeadline){
    C.lease.assert(lease);var s=C.readState(id),p=config.platforms[id];
    if(s.running){C.record(id,C.result(id,'failed','interrupted'),s.running.mode==='auto'?'auto':'manual',s);s=C.readState(id);}
    if(mode==='auto'&&!C.due(id,config,s))return null;
    if(!p.enabled)return C.record(id,C.result(id,'skipped','disabled'),mode,s);
    var minute=C.day()+'T'+C.hm();
    if(s.lastMinute===minute)return C.record(id,C.result(id,'skipped','minute'),mode,s);
    if(s.cooldownUntil>C.now()){
      if(mode==='auto')s.autoDay=C.day();
      return C.record(id,C.result(id,'skipped','cooldown'),mode,s);
    }
    var deadline=Math.min(globalDeadline,C.now()+config.task_timeout*1000);
    s.lastMinute=minute;s.running={token:lease.token,mode:mode,at:C.iso()};
    if(mode==='auto')s.autoDay=C.day();
    C.storage.write('state.'+id,s);
    var result,credential=null;
    try{
      C.lease.assert(lease);
      if(id==='smzdm')result=C.result(id,'unsupported','unsupported',{interfaceVerified:false});
      else{
        credential=C.readCredential(id);
        if(!credential||!credential.cookie)result=C.result(id,'skipped','missing');
        else{
          C.parseCookie(id,credential.cookie);
          var ctx=C.makeContext(id,credential,config,lease,deadline);
          var login=await C.adapters[id].validateCookie(ctx);
          if(login.status==='expired'){
            C.markCredential(id,credential.revision,'expired');result=login;
          }else if(login.status!=='success'){
            C.markCredential(id,credential.revision,'validation_failed');result=login;
          }else{
            C.markCredential(id,credential.revision,'valid');
            ctx.assertActive();result=await C.adapters[id].checkin(ctx);
            if(result.status==='expired')C.markCredential(id,credential.revision,'expired');
          }
        }
      }
    }catch(e){
      result=C.fromError(id,e);
      if(credential&&['http401','expired'].indexOf(e.cc)>=0)C.markCredential(id,credential.revision,'expired');
      else if(credential&&['network','timeout','json','schema','http403','http429','redirect'].indexOf(e.cc)>=0)C.markCredential(id,credential.revision,'suspect');
    }
    C.lease.assert(lease);
    // Another credential snapshot invalidates this result; never attribute it to the new account.
    if(credential){var current=C.readCredential(id);if(!current||current.revision!==credential.revision)result=C.result(id,'failed','changed');}
    if(!result||result.platform!==id)result=C.result(id,'failed','schema');
    s=C.readState(id);
    if(['http429','risk'].indexOf(result.messageKey)>=0)s.cooldownUntil=Math.max(s.cooldownUntil||0,C.now()+15*60*1000);
    if(result.messageKey==='http403')s.cooldownUntil=Math.max(s.cooldownUntil||0,C.now()+60*60*1000);
    return C.record(id,result,mode,s);
  };
  C.notify=function(results,mode,config){
    if(!config.notify||!results.length)return;
    var counts={success:0,already:0,failed:0,skipped:0,unsupported:0};
    results.forEach(function(r){var k=r.status==='expired'?'failed':r.status;counts[k]=(counts[k]||0)+1;});
    var lines=['成功 '+counts.success+'  已签 '+counts.already+'  失败 '+counts.failed,'跳过 '+counts.skipped+'  暂不支持 '+counts.unsupported];
    results.forEach(function(r){lines.push(C.platforms[r.platform].name+'：'+C.text(r.messageKey));});
    try{$notification.post('签到中心',mode==='auto'?'自动签到执行报告':'手动签到执行报告',lines.join('\n'));}catch(e){/* OS display permissions are outside the script. */}
  };
  C.dispatch=async function(mode,platform,config){
    if(['all'].concat(C.ids).indexOf(platform)<0)throw C.error('not_found');
    var ids=platform==='all'?C.ids.slice():[platform];
    if(mode==='auto')ids=ids.filter(function(id){var s=C.readState(id);return !!s.running||C.due(id,config,s);});
    if(!ids.length)return {results:[],messageKey:'not_due'};
    var lease=await C.lease.acquire(112);
    if(!lease)return {results:[],messageKey:'busy'};
    var results=[],deadline=C.now()+103000;
    try{
      for(var i=0;i<ids.length;i++){
        var id=ids[i];C.lease.assert(lease);
        if(C.now()+2000>=deadline){results.push(C.record(id,C.result(id,'skipped','budget'),mode));continue;}
        try{var r=await C.execute(id,mode,config,lease,deadline);if(r)results.push(r);}
        catch(e){if(e.cc==='lost'||e.cc==='storage')throw e;results.push(C.record(id,C.fromError(id,e),mode));}
      }
    }finally{C.lease.release(lease);}
    C.notify(results,mode,config);return {results:results};
  };
})(CC);


/* source: scripts/cookie-capture.js */
(function(C){
  C.captureEntry=function(config){
    if(typeof $request==='undefined')return {};
    var result=C.capture($request,config);
    if(result.captured&&result.changed&&config.notify){
      try{$notification.post('签到中心',C.platforms[result.platform].name,C.text('captured'));}catch(e){}
    }
    return {}; // no header/body modification
  };
})(CC);


