/* source: scripts/manual-checkin.js */
(function(C){
  C.command=async function(input,config){
    if(typeof input!=='string'||input.length>24000)throw C.error('command');
    var obj;try{obj=JSON.parse(input);}catch(e){throw C.error('command');}
    if(!obj||typeof obj!=='object'||Array.isArray(obj))throw C.error('command');
    if(obj.action==='cookie'){
      if(C.ids.indexOf(obj.platform)<0)throw C.error('not_found');
      C.saveCookie(obj.platform,obj.cookie,'manual');
      return {title:'Cookie管理',content:C.platforms[obj.platform].name+'：'+C.text('captured'),icon:'key.fill','icon-color':'3B82F6'};
    }
    if(obj.action==='clearCookie'){
      if(C.ids.indexOf(obj.platform)<0||obj.confirm!==obj.platform)throw C.error('command');
      C.storage.write('cred.'+obj.platform,{v:1,cookie:'',revision:C.token(),status:'absent',capturedAt:null,validatedAt:null,source:'manual'});
      return {title:'Cookie管理',content:C.text('cookie_cleared')};
    }
    if(obj.action==='set'){
      var patch=C.validatePatch(obj.settings),saved=C.storage.read('config',{v:1,patch:{}});
      var merged=C.validatePatch(saved.patch);
      C.mergeConfig(merged,patch);C.storage.write('config',{v:1,patch:merged});
      return {title:'设置已保存',content:C.text('manual_saved')+'\n本地设置优先于模块参数。'};
    }
    if(obj.action==='run')return C.manualRun(obj.platform||'all',config);
    if(obj.action==='history'){
      var days=obj.days===undefined?7:obj.days,platform=obj.platform||'all';
      if([7,30].indexOf(days)<0||['all'].concat(C.ids).indexOf(platform)<0)throw C.error('command');
      var s=C.getStatistics(days,platform);
      return {title:'本地历史 · '+days+'天',content:s.history.length?s.history.slice(0,60).map(function(r){return r.date+' '+C.shortTime(r.time)+' '+C.platforms[r.platform].name+' '+C.statusLabel(r.status)+' '+C.text(r.messageKey);}).join('\n'):'暂无记录'};
    }
    throw C.error('command');
  };
  C.manualRun=async function(platform,config){
    var report=await C.dispatch('manual',platform,config);
    return {title:'手动签到',content:report.results.length?report.results.map(function(r){return C.platforms[r.platform].name+'：'+C.text(r.messageKey);}).join('\n'):C.text(report.messageKey||'not_due')};
  };
})(CC);


/* source: scripts/panel.js */
(function(C){
  C.statusLabel=function(status){return {success:'成功',already:'已签到',failed:'失败',expired:'Cookie失效',skipped:'跳过',unsupported:'暂不支持'}[status]||'待执行';};
  C.shortTime=function(iso){if(!iso)return '—';var t=Date.parse(iso);return isFinite(t)?C.hm(t):'—';};
  C.displayDate=function(iso){if(!iso)return '—';var t=Date.parse(iso);return isFinite(t)?C.day(t)+' '+C.hm(t):'—';};
  C.panel=function(view,config){
    var stats=C.getStatistics(config.history_days,config.history_platform),lines=[],title,icon;
    if(view==='platforms'){
      title='平台管理';icon='square.stack.3d.up.fill';
      C.ids.forEach(function(id,index){
        var p=config.platforms[id],cred=C.readCredential(id),last=stats.platforms[id].last;
        if(index)lines.push('');
        lines.push(C.platforms[id].name+'  ·  '+(p.enabled?'启用':'停用'));
        lines.push('Cookie  '+C.cookieLabel(cred));
        lines.push('自动  '+(p.auto?'开':'关')+'   时间  '+(p.time==='follow'?'跟随 '+config.time:p.time));
        lines.push('最近  '+(last?C.statusLabel(last.status)+' · '+C.shortTime(last.time):'暂无记录'));
        lines.push('捕获  '+(cred?C.displayDate(cred.capturedAt):'未获取'));
        lines.push('验证  '+(cred?C.displayDate(cred.validatedAt):'尚未验证'));
        lines.push(C.platforms[id].level);
      });
      lines.push('','开关/时间通过“CC管理命令”更新；此面板只读。');
    }else if(view==='statistics'){
      title='签到统计';icon='chart.bar.xaxis';
      lines.push('今日完成  '+stats.completed+' / '+stats.total+'   '+(stats.total?Math.round(stats.completed/stats.total*100):0)+'%');
      lines.push('成功 '+stats.today.success+'  已签 '+stats.today.already+'  失败 '+stats.today.failed);
      lines.push('跳过 '+stats.today.skipped+'  待执行 '+stats.today.pending+'  暂不支持 '+stats.today.unsupported);
      lines.push('累计执行记录  '+stats.executions);
      lines.push('','近 '+config.history_days+' 天 · '+(config.history_platform==='all'?'全部平台':C.platforms[config.history_platform].name));
      C.ids.filter(function(id){return config.history_platform==='all'||config.history_platform===id;}).forEach(function(id){
        var p=stats.platforms[id];lines.push(C.platforms[id].name+'  '+(p.successRate===null?'无足够样本':p.successRate+'% 成功率'));
        if(p.observedStreak!==null)lines.push('本地已观察连续完成 '+p.observedStreak+' 天（非账号历史）');
      });
      lines.push('','最近记录');
      if(!stats.history.length)lines.push('暂无执行记录');
      stats.history.slice(0,8).forEach(function(r){lines.push(r.date.slice(5)+' '+C.shortTime(r.time)+' '+C.platforms[r.platform].name+' '+C.statusLabel(r.status)+' · '+(r.mode==='auto'?'自动':'手动'));});
      lines.push('','成功率仅计成功/已签/失败/失效；不推算奖励。');
    }else{
      title='CHECKIN CENTER';icon='checkmark.circle.fill';
      var all=C.getStatistics(7,'all');
      lines.push('多平台签到中心  ·  V'+C.version);
      lines.push('','今日完成  '+all.completed+' / '+all.total);
      lines.push('成功 '+all.today.success+'  已签 '+all.today.already+'  失败 '+all.today.failed);
      lines.push('待执行 '+all.today.pending+'  跳过 '+all.today.skipped+'  不支持 '+all.today.unsupported);
      lines.push('','平台签到状态');
      C.ids.forEach(function(id){var r=all.platforms[id].today;lines.push(C.platforms[id].name+'  '+(r?C.statusLabel(r.status)+' · '+C.shortTime(r.time):'待执行'));});
      lines.push('','统一时间  '+config.time+'  ·  自动 '+(config.auto?'开启':'关闭'));
      lines.push('Cookie捕获 '+(config.capture?'开启':'关闭')+'  ·  本机时区');
      lines.push('','最近执行');
      if(!all.history.length)lines.push('暂无记录；未获取Cookie时不会伪造签到。');
      all.history.slice(0,3).forEach(function(r){lines.push(C.shortTime(r.time)+' '+C.platforms[r.platform].name+' '+C.statusLabel(r.status));});
      lines.push('','刷新只读；运行“CC一键签到”执行。','后台可能延迟，不保证锁屏准点。');
    }
    return {title:title,content:lines.join('\n'),icon:icon,'icon-color':'3B82F6'};
  };
})(CC);


/* source: scripts/main.js */
(function(C){
  C.main=async function(){
    var finished=false,action='unknown',config;
    function done(value){if(finished)return;finished=true;C.stopped=true;$done(value||{});}
    try{
      var args=C.parseArgument(typeof $argument==='undefined'?'':$argument);
      action=args.action||'panel';config=C.getConfig(args);
      if(action==='capture'){done(C.captureEntry(config));return;}
      if(action==='panel'){done(C.panel(args.view||'overview',config));return;}
      // JSC only provides setTimeout, so all timer callbacks are guarded.
      setTimeout(function(){done({title:'签到中心',content:C.text('budget'),style:'alert'});},110000);
      if(action==='schedule'){await C.schedule(config);done({});return;}
      if(action==='run'){done(await C.manualRun(args.platform||'all',config));return;}
      if(action==='command'){
        var parameter=typeof $intent!=='undefined'&&$intent?$intent.parameter:undefined;
        if(parameter===undefined){done({title:'管理命令',content:'通过快捷指令运行“CC管理命令”，传入JSON参数。\n详见COOKIE.md与SCHEDULE.md。\n此入口未收到参数，未修改任何设置。'});return;}
        done(await C.command(parameter,config));return;
      }
      throw C.error('config');
    }catch(e){
      var code=e&&C.own(C.messages,e.cc)?e.cc:'internal';
      if(typeof console!=='undefined')console.log('[Checkin Center] '+code);
      done(action==='capture'?{}:{title:'签到中心',content:C.text(code),style:'error'});
    }
  };
})(CC);

CC.main();
